diff --git a/tests/anthropicSdk1.test.ts b/tests/anthropicSdk1.test.ts
new file mode 100644
index 0000000..ef8b9f8
--- /dev/null
+++ b/tests/anthropicSdk1.test.ts
@@ -0,0 +1,24 @@
+import { describe, expect, it } from 'vitest';
+import Anthropic from '@anthropic-ai/sdk';
+import { buildRequest } from '../harvest/lib/extract';
+
+describe('anthropic sdk 1.x', () => {
+  it('is 1.x and sends API version 2026-10-21 without sampling params', async () => {
+    let headers: Headers | undefined;
+    let body: Record<string, unknown> = {};
+    const client = new Anthropic({
+      apiKey: 'dummy',
+      fetch: (async (_u: unknown, init: RequestInit) => {
+        headers = new Headers(init.headers);
+        body = JSON.parse(String(init.body));
+        return new Response(
+          JSON.stringify({ id: 'm', type: 'message', role: 'assistant', model: 'x', content: [], stop_reason: 'end_turn', usage: { input_tokens: 1, output_tokens: 1 } }),
+          { headers: { 'content-type': 'application/json' } },
+        );
+      }) as never,
+    });
+    await client.messages.create(buildRequest({ id: 'c', name: 'C' } as never, []));
+    expect(headers?.get('anthropic-version')).toBe('2026-10-21');
+    for (const k of ['temperature', 'top_p', 'top_k']) expect(body).not.toHaveProperty(k);
+  });
+});
